}

func applyReviewConfig(runCfg *reviewtypes.RunConfig, cfg settings.ReviewConfig) {
	runCfg.Skills = cfg.Skills
	if len(cfg.Skills) == 0 {
		runCfg.PromptOverride = cfg.Prompt
		return
	}
	runCfg.AlwaysPrompt = cfg.Prompt
}

